<template>
  <div></div>
</template>

<script>
import { post } from "@/utils/proxy";

export default {
  props: {
    value: {},
    extraQueryOptions: {},
    fromFile: {
      type: String,
      required: true
    },
    isRefresh: {},
    onLoading: {},
    onLoaded: {}
  },
  data() {
    return {
      data: [],
      queryOptionsLoaded: false
    };
  },
  methods: {
    getQueryServiceOptions() {
      post("base/service/getQueryServiceOptions", { name: this.fromFile }).then(
        response => {
          this.queryServiceOptions = response;
          this.getData();
        },
      );
    },
    getData() {
      if (this.onLoading) {
        this.onLoading();
      }
      this.selectedRow = [];
      const params = {
        name: this.fromFile
      };

      if (this.extraQueryOptions) {
        params.where = this.extraQueryOptions;
      }

      post("base/service/getData", params).then(response => {
        this.data = response.data;
        if (this.onLoaded) {
          this.onLoaded(response.data);
        }
        this.$emit("input", this.data);
      });
    }
  },
  created() {
    this.getData();
  },
  watch: {
    extraQueryOptions: {
      handler() {
        this.getData();
      },
      deep: true
    },
    isRefresh: {
      handler() {
        this.getData();
      },
      deep: true
    }
  },
  computed: {}
};
</script>

<style lang="css">
</style>



