<template>
  <div
    id="app"
    v-resize="onResize"
  >
    <router-view></router-view>
    <query-service
      from-file="app_settings"
      :on-loaded="onLoadedAppSettings"
    />
  </div>
</template>
<script>
export default {
  mounted() {
    this.onResize();
  },
  methods: {
    onLoadedAppSettings(data) {
      const appSettingsData = {};
      data[0].forEach(item => {
        appSettingsData[item.id] = item.value;
      });
      this.$store.dispatch("app/setAppSettings", appSettingsData);
    },
    onResize() {
      this.$store.dispatch("app/windowResize", {
        x: window.innerWidth,
        y: window.innerHeight
      });
    }
  }
};
</script>



