import * as types from "./mutation-types";

export const windowResize = async ({ commit }, coordinat) => {
  commit(types.WINDOW_RESIZE, coordinat);
};

export const setAppSettings = async ({ commit }, data) => {
  commit(types.APP_SETTINGS, data);
};


export default {
  windowResize,
  setAppSettings
};



