import lodash from "lodash";
import moment from "moment";

let pdf = {};

function resolveFormGroup(columns) {
  let cols = [];

  columns.forEach(function (col) {
    let children = [];
    col.forEach(function (child) {
      if (child ? !child.hidden : false) {
        if (child.formGroups) {
          let resFormGroup = resolveFormGroup(child.formGroups);
          if (resFormGroup.length > 0) {
            children.push({
              columns: resolveFormGroup(child.formGroups)
            });
          }
        } else {
          let content = {};

          if (child.image) {
            content = {
              image: (child.image == 'N' ? 'noImage' : child.image),
              fit: [child.imageWidth || '*', child.imageHeight || 50]
            };
          } else if (child.checkbox) {
            content = {
              image: child.checkbox == 'Y' ? 'check' : 'uncheck',
              fit: [child.size || 8, child.size || 8],
              width: child.width || 10,
              style: 'checkbox'
            };
          } else {
            let text = child.value;
            content = {
              text: text || '',
              width: child.valueWidth || '*',
              style: child.style || 'value'
            };
          }

          children.push({
            columns: [{
              text: child.label || '-',
              width: child.labelWidth || 100,
              style: child.style
            }, content],
            style: 'formGroup'
          });
        }
      }
    });

    cols.push(children);
  });

  return cols;
}

function resolveColumn(columns) {
  let cols = [];
  columns.forEach(function (col) {
    let children = [];
    let childrenContent = [];
    let totalWidth = 0;
    let colState = 0;
    col.forEach(function (child) {
      let content = {};
      let colWidth = '100%';
      let alignment = 'left';
      let colClassSplit = child.colClass ? child.colClass.split(',') : ['p'];

      colState++;

      if (child.width) {
        colWidth = child.width;
        totalWidth = 0;
      } else if (child.colMd) {
        colWidth = getColWidth(child.colMd);
        totalWidth += child.colMd;
      } else {
        totalWidth = 12;
      }

      if (child.colGroups) {
        childrenContent.push({
          width: colWidth,
          columns: resolveColumn(child.colGroups),
          style: colClassSplit
        });
      }
      if (child.panel) {
        childrenContent.push({
          width: colWidth,
          columns: [resolvePanel(child.panel)],
          style: colClassSplit
        });
      } else if (child.image) {
        let imageCol = {};

        imageCol.columns = [{
          image: (child.image == 'N' ? 'noImage' : child.image),
          fit: child.noFit ? null : [child.imageWidth || '*', child.imageHeight || 50]
        }];

        if (child.colMd) {
          imageCol.width = getColWidth(child.colMd);
          imageCol.style = colClassSplit;
        } else if (child.noFit) {
          imageCol.width = child.imageWidth || '100%';
        }

        children.push(imageCol);
      } else if (child.formGroups) {
        children.push({
          width: colWidth,
          columns: resolveFormGroup(child.formGroups),
          style: colClassSplit
        });
      } else if (child.table) {
        children.push({
          width: colWidth,
          columns: [resolveTable(child.table)],
          style: colClassSplit
        });
      } else {
        let i = 0;
        colClassSplit.forEach(function (item) {
          colClassSplit[i] = item.trim();
          i++;
        });

        if (child.align) {
          alignment = child.align;
        }
        if (child.checkbox) {
          content = {
            image: child.checkbox ? 'check' : 'uncheck',
            fit: [child.size || 8, child.size || 8],
            width: child.width || 10,
            style: 'checkbox'
          };
        } else if (child.pagebreak) {
          content = ({
            text: ' ',
            fontSize: 1,
            pageBreak: 'after',
            margin: [0, 0, 0, 0]
          });
        } else if (child.break) {
          content = ({
            text: ' ',
            fontSize: 1,
            margin: [0, 10, 0, 10],
            width: '100%'
          });
        }
        else if (child.text) {
          content = {
            text: child.text || '',
            width: colWidth,
            alignment: alignment,
            style: colClassSplit
          };
          if (child.decoration) {
            content.decoration = child.decoration;
            if (child.decorationStyle) content.decorationStyle = child.decorationStyle;
          }
        }
        else if (child.canvas) {
          content = {
            canvas: child.canvas
          }
        }
        else if (child.cTable) {
          content = {
            table: child.cTable,
            width: colWidth,
            style: colClassSplit
          }
          if (child.cTableLayout) {
            content = Object.assign(content, {
              layout: child.cTableLayout
            })
          }
        }
        
        if(child.pageOrientation) {
          content = Object.assign(content, {
            pageOrientation: child.pageOrientation
          })
        }
        if(child.pageBreak) {
          content = Object.assign(content, {
            pageBreak: child.pageBreak
          })
        }

        childrenContent.push(content);
      }

      if (childrenContent.length > 0) {
        if (totalWidth >= 12) {
          children.push({
            columns: childrenContent
          });
          childrenContent = [];
          totalWidth = 0;
        } else if (colState == col.length) {
          children.push({
            columns: childrenContent
          });
        }
      }
    });

    cols.push(children);
  });

  return cols;
}

function resolvePanel(panel) {
  return {
    table: {
      'widths': [
        '*'
      ],
      body: [
        [
          {
            columns: resolveColumn(panel.colGroups),
            fillColor: panel.background || '#eeeeee',
            color: panel.color || '#000000',
            padding: [5, 5, 5, 5],
            border: [false, false, false, false]
          }
        ]
      ]
    }
  };
}

function resolveContent(content) {
  let result = [];
  content.forEach(function (val) {
    result.push(resolveChildContent(val));
  });

  return result;
}

function resolveTable(table) {
  let body = [];

  // resolve fields
  let fields = [];
  let widths = [];

  let autoNumber = 0;

  if (table.showNumber) {

    autoNumber = lodash.findIndex(table.fields, function (o) {
      return o.id == 'no';
    });

    // resolve header
    if (autoNumber == -1) {
      fields.push({
        text: 'No.',
        style: 'tableHeader'
      });
      widths.push("auto");
    }
  }

  // resolve title
  if (table.title) {
    let title = [];

    title.push({
      text: table.title || '',
      colSpan: table.fields.length + (table.showNumber && autoNumber > -1 ? 1 : 0),
      style: 'tableHeader'
    });

    lodash.range(table.fields.length - 1).forEach(function () {
      title.push({ text: '' });
    });

    body.push(title);
  }

  // resolve subtitle
  if (table.subTitles) {
    table.subTitles.forEach(function (subTitle) {
      let subTitles = [];
      subTitles.push({
        text: subTitle || '',
        colSpan: table.fields.length + (table.showNumber && autoNumber > -1 ? 1 : 0),
        style: 'tableHeader'
      });

      lodash.range(table.fields.length - 1).forEach(function () {
        subTitles.push({ text: '' });
      });

      body.push(subTitles);
    });
  }

  table.fields.forEach(function (field) {
    fields.push({
      text: field.title || 'Undefined',
      style: 'tableHeader'
    });

    if (field.id == 'no') {
      widths.push("auto");
    }
    else {
      widths.push(lodash.isNumber(field.width || field.widthExport) ? (field.width || field.widthExport) : '*');
    }
  });

  body.push(fields);

  // resolve row
  table.data.forEach(function (row, key) {
    let data = [];
    if (table.showNumber && autoNumber == -1) {
      data.push({
        text: (key + 1).toString(),
        style: 'tableBody'
      });
    }

    table.fields.forEach(function (field) {
      let text = '';
      let image = '';
      let value;

      if (row[field.id] && row[field.id].text) {
        value = row[field.id].text;
      } else {
        value = row[field.id];
      }

      if (field.type == 'date') {
        text = moment(value).format("DD, MMMM YYYY");
      } else if (field.type == 'checkbox') {
        image = value == 'Y' ? 'check' : 'uncheck';
      } else if (field.type == 'native') {
        text = field.id;
      }
      else if (field.type == 'defaultValue') {
        text = (value) == null ? field.default : (value);
      }
      else {
        if (Array.isArray(field.id)) {
          field.id.forEach(function (val, key) {
            if (key > 0) {
              text += field.concat || ' ';
            }
            text += ((row[val]) || '').toString();
          });
        } else {
          text = (value || '').toString();
        }
      }

      if (image != '') {
        data.push({
          image: image,
          fit: [field.size || 8, field.size || 8],
          width: field.width || 10,
          style: 'tableBody checkbox'
        });
      } else {
        data.push({
          text: text || '',
          style: row[field.id] && row[field.id].style ? row[field.id].style : 'tableBody',
          colSpan: row[field.id] && row[field.id].colSpan ? row[field.id].colSpan : 0
        });
      }
    });

    body.push(data);
  });

  let isFooterExist = lodash.filter(table.fields, function (f) {
    return f.footer != undefined;
  }).length > 0;

  // resolve footer
  if (isFooterExist) {
    let footers = [];

    if (table.showNumber && autoNumber == -1) {
      footers.push({
        text: '', style: 'tableHeader'
      });
    }

    table.fields.forEach(function (field) {
      footers.push({
        text: field.footer || '',
        style: 'tableHeader'
      });
    });

    body.push(footers);
  }

  return {
    table: {
      headerRows: 1,
      keepWithHeaderRows: 1,
      widths: widths,
      body: body,
      style: 'table'
    },
    layout: table.layout
  };
}

function resolveChildContent(item) {
  let result = [];
  for (var key in item) {
    const val = item[key];
    let resultObj = {};
    if (key.toLowerCase() == 'title') {
      resultObj = {
        text: val || '',
        style: 'header'
      };
      result.push(resultObj);
    } else if (key.toLowerCase() == 'subtitle') {
      resultObj = {
        text: val || '',
        style: 'subHeader'
      };
      result.push(resultObj);
    } else if (key.toLowerCase() == 'text') {
      result.push({
        text: val || ''
      });

    } else if (key.toLowerCase() == 'formgroups') {
      resultObj = {
        columns: resolveFormGroup(val),
        style: 'container'
      };
      result.push(resultObj);
    } else if (key.toLowerCase() == 'colgroups') {
      resultObj = resolveColumn(val);
      result.push(resultObj);
    } else if (key.toLowerCase() == 'table') {
      result.push(resolveTable(val));
    } else if (key.toLowerCase() == 'canvas') {
      result.push({
        canvas: val,
        width: '100%'
      });
    } else if (key.toLowerCase() == 'pagebreak') {
      result.push({
        text: ' ',
        fontSize: 1,
        pageBreak: val || 'after',
        margin: [0, 0, 0, 0]
      });
    } else if (key.toLowerCase() == 'break') {
      result.push({
        text: ' ',
        fontSize: 1,
        margin: [0, 10, 0, 10],
        width: '100%'
      });
    }
  }
  return result;
}

function getContentById(id) {
  function ParseContainer(cnt, e, p, styles) {
    let elements = [];
    let children = e.childNodes;
    if (children.length != 0) {
      for (let i = 0; i < children.length; i++) p = ParseElement(elements, children[i], p, styles);
    }
    if (elements.length != 0) {
      for (let i = 0; i < elements.length; i++) cnt.push(elements[i]);
    }
    return p;
  }

  function ComputeStyle(o, styles) {
    for (let i = 0; i < styles.length; i++) {
      let st = styles[i].trim().toLowerCase().split(':');
      if (st.length == 2) {
        switch (st[0].trim()) {
          case 'font-size': {
            o.fontSize = parseInt(st[1]);
            break;
          }
          case 'text-align': {
            switch (st[1].trim()) {
              case 'right':
                o.alignment = 'right';
                break;
              case 'center':
                o.alignment = 'center';
                break;
            }
            break;
          }
          case 'font-weight': {
            switch (st[1].trim()) {
              case 'bold':
                o.bold = true;
                break;
            }
            break;
          }
          case 'text-decoration': {
            switch (st[1].trim()) {
              case 'underline':
                o.decoration = 'underline';
                break;
            }
            break;
          }
          case 'font-style': {
            switch (st[1].trim()) {
              case 'italic':
                o.italics = true;
                break;
            }
            break;
          }
        }
      }
    }
  }

  function ParseElement(cnt, e, p, styles) {
    if (!styles) styles = [];
    if (e.getAttribute) {
      let nodeStyle = e.getAttribute('style');
      if (nodeStyle) {
        let ns = nodeStyle.split(';');
        for (let k = 0; k < ns.length; k++) styles.push(ns[k]);
      }
    }

    switch (e.nodeName.toLowerCase()) {
      case '#text': {
        let t = {
          text: e.textContent.replace(/\n/g, '')
        };
        if (styles) ComputeStyle(t, styles);
        p.text.push(t);
        break;
      }
      case 'b':
      case 'strong': {
        //styles.push("font-weight:bold");
        ParseContainer(cnt, e, p, styles.concat(['font-weight:bold']));
        break;
      }
      case 'u': {
        //styles.push("text-decoration:underline");
        ParseContainer(cnt, e, p, styles.concat(['text-decoration:underline']));
        break;
      }
      case 'i': {
        //styles.push("font-style:italic");
        ParseContainer(cnt, e, p, styles.concat(['font-style:italic']));
        //styles.pop();
        break;
        //cnt.push({ text: e.innerText, bold: false });
      }
      case 'span': {
        ParseContainer(cnt, e, p, styles);
        break;
      }
      case 'br': {
        p = CreateParagraph();
        cnt.push(p);
        break;
      }
      case 'table': {
        let t = {
          table: {
            widths: [],
            body: []
          }
        };
        let border = e.getAttribute('border');
        let isBorder = false;
        if (border)
          if (parseInt(border) == 1) isBorder = true;
        if (!isBorder) t.layout = 'noBorders';
        ParseContainer(t.table.body, e, p, styles);

        let widths = e.getAttribute('widths');
        if (!widths) {
          if (t.table.body.length != 0) {
            if (t.table.body[0].length != 0)
              for (let k = 0; k < t.table.body[0].length; k++) t.table.widths.push('*');
          }
        } else {
          let w = widths.split(',');
          for (let k = 0; k < w.length; k++) t.table.widths.push(w[k]);
        }
        cnt.push(t);
        break;
      }
      case 'tbody': {
        ParseContainer(cnt, e, p, styles);
        //p = CreateParagraph();
        break;
      }
      case 'tr': {
        let row = [];
        ParseContainer(row, e, p, styles);
        cnt.push(row);
        break;
      }
      case 'td': {
        p = CreateParagraph();
        let st = {
          stack: []
        };

        st.stack.push(p);

        let rspan = e.getAttribute('rowspan');
        if (rspan) st.rowSpan = parseInt(rspan);
        let cspan = e.getAttribute('colspan');
        if (cspan) st.colSpan = parseInt(cspan);

        ParseContainer(st.stack, e, p, styles);
        cnt.push(st);
        break;
      }
      case 'div':
      case 'p': {
        p = CreateParagraph();
        let st = {
          stack: []
        };
        st.stack.push(p);
        ComputeStyle(st, styles);
        ParseContainer(st.stack, e, p);

        cnt.push(st);
        break;
      }
      case 'h1': {
        ParseContainer(cnt, e, p, styles.concat(['font-size:32px']));
        break;
      }
      case 'h2': {
        ParseContainer(cnt, e, p, styles.concat(['font-size:24px']));
        break;
      }
      case 'h3': {
        ParseContainer(cnt, e, p, styles.concat(['font-size:19px']));
        break;
      }
      case 'h4': {
        ParseContainer(cnt, e, p, styles.concat(['font-size:16px']));
        break;
      }
      case 'h5': {
        ParseContainer(cnt, e, p, styles.concat(['font-size:14px']));
        break;
      }
      case 'h6': {
        ParseContainer(cnt, e, p, styles.concat(['font-size:13px']));
        break;
      }
      case 'img': {
        let maxResolution = {
          width: 570,
          height: 830
        };

        let width = parseInt(e.getAttribute('width')) || 570;
        let height = parseInt(e.getAttribute('height'));

        if (width > maxResolution.width) {
          let scaleByWidth = maxResolution.width / width;
          width = (width * scaleByWidth) - 50;
          height = (height * scaleByWidth) - 50;
        }
        if (height > maxResolution.height) {
          let scaleByHeight = maxResolution.height / height;
          width = (width * scaleByHeight) - 50;
          height *= (height * scaleByHeight) - 50;
        }

        let myImage = {
          image: e.getAttribute('src'),
          width: width,
          height: height
        };

        cnt.push(myImage);
        break;
      }
      default: {
        console.log('Parsing for node ' + e.nodeName + ' not found');
        break;
      }
    }
    return p;
  }

  function ParseHtml(cnt, htmlText) {
    let html = $(htmlText.replace(/\t/g, '').replace(/\n/g, ''));
    let p = CreateParagraph();
    for (let i = 0; i < html.length; i++) ParseElement(cnt, html.get(i), p);
  }

  function CreateParagraph() {
    let p = {
      text: []
    };
    return p;
  }

  let content = [];
  ParseHtml(content, document.getElementById(id).outerHTML);
  return content;
}

function getColWidth(w) {
  return getColWidthNumeric(w) + '%';
}

function getColWidthNumeric(w) {
  let colWidth;
  switch (w) {
    case 12:
      colWidth = 100;
      break;
    case 11:
      colWidth = 91.66666667;
      break;
    case 10:
      colWidth = 83.33333333;
      break;
    case 9:
      colWidth = 75;
      break;
    case 8:
      colWidth = 66.66666667;
      break;
    case 7:
      colWidth = 58.33333333;
      break;
    case 6:
      colWidth = 50;
      break;
    case 5:
      colWidth = 41.66666667;
      break;
    case 4:
      colWidth = 33.33333333;
      break;
    case 3:
      colWidth = 25;
      break;
    case 2:
      colWidth = 16.66666667;
      break;
    case 1:
      colWidth = 8.33333333;
      break;
    default:
      colWidth = 100;
  }
  return colWidth;
}

function getMargin(tType, tMargin) {
  let m = tMargin;

  let margin = [];
  switch (tType) {
    case 'a':
      margin = {
        margin: [m, m, m, m]
      };
      break;

    case 'l':
      margin = {
        marginLeft: 0
      };
      break;

    case 't':
      margin = {
        marginTop: m
      };
      break;

    case 'r':
      margin = {
        marginRight: m
      };
      break;

    case 'b':
      margin = {
        marginBottom: m
      };
      break;

    case 'y':
      margin = {
        margin: [0, m, 0, m]
      };
      break;

    case 'x':
      margin = {
        margin: [m, 0, m, 0]
      };
      break;

    default:
    // code
  }

  return margin;
}

