<template>
  <v-layout justify-center class="modal-content">
    <v-card class="white confirmation-content">
      <v-toolbar height="50" flat>
        <v-toolbar-title>{{title}}</v-toolbar-title>
        <v-spacer></v-spacer>
        <v-btn icon @click.native="cancel()">
          <v-icon>close</v-icon>
        </v-btn>
      </v-toolbar>
      <v-divider></v-divider>
      <v-card-text>{{message}}</v-card-text>
      <v-divider></v-divider>
      <v-card-actions>
        <v-spacer></v-spacer>
        <v-btn class="green--text darken-1" flat="flat" @click="ok">OK</v-btn>
        <v-btn class="red--text darken-1" flat="flat" @click="cancel">Cancel</v-btn>
      </v-card-actions>
    </v-card>
  </v-layout>
</template>

<script>
export default {
  props: {
    title: {
      type: String,
      default: () => "Confirmation"
    },
    message: {
      type: String,
      default: () => "-"
    }
  },
  data() {
    return {};
  },
  methods: {
    ok() {
      this.$vuedals.close(true);
    },
    cancel() {
      this.$vuedals.close(false);
    }
  }
};
</script>


