<template>
  <v-card class="elevation-3">
    <v-data-table
      flat
      :headers="columns"
      :items="data"
      v-bind:pagination.sync="paginationSort"
      hide-actions
      :loading="loading"
    >
      <template slot="items" slot-scope="props">
        <slot v-if="hasTemplate" name="items" :item="props.item" :index="props.index"></slot>
        <tr
          v-else
          :active="getActiveSelectedRow(props.item)"
          @click="selectRow(props, $event)"
          :style="{cursor:'pointer'}"
          v-hotkey="keymap"
          :class="props.index%2==0 ? 'even': 'odd'"
        >
          <td
            v-if="showNumber"
            :style="{width:'30px !important'}"
          >{{ (props.index) + ((pagination.page-1) * pagination.rowsPerPage) + 1 }}</td>
          <td
            v-for="item in visibleColumns"
            v-bind:key="item[primaryKey]"
            :style="{textAlign: item.align}"
          >
            <div v-if="item.type" :style="{width: `${item.width}px !important`}">
              <span
                v-if="item.type=='date'"
              >{{formatDate(props.item[item.value], item.options.format)}}</span>
              <span v-else-if="item.type=='currency'">{{formatCurrency(props.item[item.value])}}</span>
              <span v-else-if="item.type=='enum'">{{item.options.data[props.item[item.value]]}}</span>
              <span v-else>{{ props.item[item.value] }}</span>
            </div>
            <div :style="{width: `${item.width}px !important`}" v-else>{{ props.item[item.value] }}</div>
          </td>
        </tr>
      </template>
    </v-data-table>
    <v-divider v-show="showPagination"></v-divider>
    <v-layout row wrap class="mt-2" v-show="totalRows > pagination.rowsPerPage && showPagination">
      <v-flex xs12 md9>
        <div class="py-3">
          <!-- <div class="px-3 mb-3">
            Showing
            <b>{{((pagination.page-1) * pagination.rowsPerPage) + 1}}</b>
            to
            {{((pagination.page-1) * pagination.rowsPerPage) + data.length}} of
            {{totalRows}} rows
          </div> -->
          <v-pagination v-model="pagination.page" :length="pages" :total-visible="10" circle></v-pagination>
        </div>
      </v-flex>
      <v-flex xs12 md3>
        <div class="pa-2">
          <v-select
            class="mt-2"
            v-model="pagination.rowsPerPage"
            v-bind:items="[10, 25, 50, 100]"
            label="Rows per page"
          ></v-select>
        </div>
      </v-flex>
    </v-layout>
  </v-card>
</template>

<script>
import _ from "lodash";
import moment from "moment";

import { post } from "@/utils/proxy";
import { confirm, downloadExcel } from "@/utils/modal";

export default {
  props: {
    extraQueryOptions: {},
    fromFile: {
      type: String,
      required: true
    },
    rowsPerPage: {},
    defaultSort: {},
    isRefresh: {},
    isRefreshColumns: {},
    isDelete: {},
    isRecoverDelete: {},
    isPermanentDelete: {},
    isDownload: {},
    onSelect: {},
    onDeleted: {},
    hasTemplate: {},
    getTotalRows: {},
    getItems: {},
    getColumns: {},
    showNumber: {
      type: Boolean,
      default: false
    },
    showPagination: {
      type: Boolean,
      default: true
    },
    responseCallback: {},
    showAll: {}
  },
  data() {
    return {
      primaryKey: "",
      columns: [],
      data: [],
      pagination: {
        page: 1,
        sortBy: null,
        rowsPerPage: 25
      },
      totalRows: 0,
      paginationSort: {},
      queryOptionsLoaded: false,
      selectedRow: [],
      primaryKeySelectedId: [],
      lastClickIndex: 0,
      params: {},
      tableViewOptionsLoaded: false,
      loading: false,
      showNumberIndex: -1
    };
  },
  methods: {
    getActiveSelectedRow(item) {
      const index = _.findIndex(
        this.selectedRow,
        o => o[this.primaryKey] === item[this.primaryKey]
      );
      return index >= 0;
    },
    selectAll() {
      this.selectedRow = [];
      this.primaryKeySelectedId = [];
      this.data.forEach(item => {
        this.selectedRow.push(item);
        this.primaryKeySelectedId.push(item[this.primaryKey]);
      });
    },
    selectRow(props, e) {
      if (this.onSelect) {
        document.onselectstart = () => false;
        if (e.shiftKey) {
          this.selectedRow = [];
          let startIndex = 0;
          let endIndex = 0;
          if (this.lastClickIndex < props.index) {
            startIndex = this.lastClickIndex;
            endIndex = props.index;
          } else {
            startIndex = props.index;
            endIndex = this.lastClickIndex;
          }
          for (let i = startIndex; i <= endIndex; i += 1) {
            this.selectedRow.push(this.data[i]);
          }
        } else {
          this.lastClickIndex = props.index;
          if (e.metaKey || e.ctrlKey) {
            const index = _.findIndex(
              this.selectedRow,
              o => o[this.primaryKey] === props.item[this.primaryKey]
            );
            if (index === -1) this.selectedRow.push(props.item);
            else this.selectedRow.splice(index, 1);
          } else if (this.selectedRow.length === 1) {
            if (
              this.selectedRow[0][this.primaryKey] ===
              props.item[this.primaryKey]
            ) {
              this.selectedRow = [];
            } else {
              this.selectedRow = [];
              this.selectedRow.push(props.item);
            }
          } else {
            this.selectedRow = [];
            this.selectedRow.push(props.item);
          }
        }
        this.primaryKeySelectedId = [];
        this.selectedRow.forEach(item => {
          this.primaryKeySelectedId.push(item[this.primaryKey]);
        });
      }
    },
    resetSelectedRow() {
      this.selectedRow = [];
    },
    getTableViewOptions() {
      this.loading = true;
      post("base/table/getTableViewOptions", { name: this.fromFile }).then(
        response => {
          this.columns = [];
          if (this.showNumber) {
            this.showNumberIndex = 0;
            this.columns.push({
              text: "No",
              align: "left",
              sortable: false,
              width: "30"
            });
          }
          this.columns = this.columns.concat(response.columns);
          this.primaryKey = response.primary_key;
          this.tableViewOptions = response;
          this.tableViewOptionsLoaded = true;
          this.getData();
          if (this.getColumns) {
            this.getColumns(response.columns);
          }
          this.tableViewOptionsLoaded = true;
        }
      );
    },
    getData() {
      this.loading = true;
      this.selectedRow = [];
      this.params = {
        name: this.fromFile
      };
      if (typeof this.tableViewOptions.query === "string") {
        if (typeof this.extraQueryOptions === "string") {
          this.params.where = this.extraQueryOptions;
        } else {
          this.params.where = Object.assign({}, this.extraQueryOptions);
        }
      } else {
        this.params.where = {
          ORDER: {
            [this.paginationSort.sortBy]: this.paginationSort.descending
              ? "DESC"
              : "ASC"
          },
          LIMIT: [
            (this.pagination.page - 1) * this.pagination.rowsPerPage,
            this.pagination.rowsPerPage
          ]
        };
        if (this.paginationSort.sortBy == null) {
          this.params.where.ORDER = null;
          if (this.defaultSort) {
            const defaultSort = this.defaultSort.split(":");
            this.params.where.ORDER = {
              [defaultSort[0]]: defaultSort[1]
            };
          }
        }

        if (this.tableViewOptions.query.where) {
          if (!this.params.where) this.params.where = {};
          this.params.where = Object.assign(
            this.params.where,
            this.tableViewOptions.query.where
          );
        }

        if (this.extraQueryOptions) {
          if (!this.params.where) this.params.where = {};
          this.params.where = Object.assign(
            this.params.where,
            this.extraQueryOptions
          );
        }
      }

      if (this.showAll) {
        delete this.params.where.LIMIT;
      }

      post("base/table/getData", this.params).then(response => {
        this.loading = false;
        if (this.responseCallback) {
          this.data = this.responseCallback(response.data, this.pagination);
        } else {
          this.data = response.data;
        }
        this.totalRows = response.total_rows;

        if (this.showAll) {
          this.pagination.rowsPerPage = response.total_rows;
        }

        if (this.getTotalRows) this.getTotalRows(response.total_rows);
        if (this.getItems) this.getItems(this.data);
      });
    },
    formatDate(date, format) {
      return moment(date)
        .locale("id")
        .format(format);
    },
    formatCurrency(value) {
      const val = parseFloat(value, 10);
      return val.toFixed(2).replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,");
    }
  },
  created() {
    if (this.rowsPerPage) this.pagination.rowsPerPage = this.rowsPerPage;
    this.getTableViewOptions();
    this.paginationSort = this.pagination;
  },
  watch: {
    pagination: {
      handler() {
        if (this.tableViewOptionsLoaded) {
          this.getData();
          this.paginationSort.rowsPerPage = this.pagination.rowsPerPage;
        }
      },
      deep: true
    },
    paginationSort: {
      handler() {
        if (this.tableViewOptionsLoaded) {
          this.getData();
        }
      },
      deep: true
    },
    extraQueryOptions: {
      handler() {
        if (this.tableViewOptionsLoaded) this.getData();
      },
      deep: true
    },
    selectedRow: {
      handler() {
        if (this.onSelect) this.onSelect(this.selectedRow);
      },
      deep: true
    },
    isRefresh: {
      handler() {
        this.selectedRow = {};
        this.getData();
      },
      deep: true
    },
    isRefreshColumns: {
      handler() {
        this.selectedRow = {};
        this.getTableViewOptions();
      },
      deep: true
    },
    isDelete: {
      handler() {
        confirm({
          message: "Are you sure you want to delete?"
        }).then(() => {
          post("base/table/submitDelete", {
            table: this.tableViewOptions.query.table,
            where: { [this.primaryKey]: this.primaryKeySelectedId }
          }).then(response => {
            if (response.success_message) {
              if (this.onDeleted) this.onDeleted(this.primaryKeySelectedId);
              this.primaryKeySelectedId = [];
              this.getData();
            }
          });
        });
      },
      deep: true
    },
    isRecoverDelete: {
      handler() {
        confirm({
          message: "Are you sure you want to recover deleted record?"
        }).then(() => {
          post("base/table/recoverDelete", {
            table: this.tableViewOptions.query.table,
            where: { [this.primaryKey]: this.primaryKeySelectedId }
          }).then(response => {
            if (response.success_message) {
              this.getData();
            }
          });
        });
      },
      deep: true
    },
    isPermanentDelete: {
      handler() {
        confirm({
          message: "Are you sure you want to permanently delete?"
        }).then(() => {
          post("base/table/permanentDelete", {
            table: this.tableViewOptions.query.table,
            where: { [this.primaryKey]: this.primaryKeySelectedId }
          }).then(response => {
            if (response.success_message) {
              this.getData();
            }
          });
        });
      },
      deep: true
    },
    isDownload: {
      handler() {
        downloadExcel({
          title: this.tableViewOptions.title || "",
          columns: this.tableViewOptions.columns,
          queryParams: this.params
        });
      },
      deep: true
    }
  },
  computed: {
    keymap() {
      return {
        "meta+a": this.selectAll,
        "ctrl+a": this.selectAll
      };
    },
    pages() {
      const pages = Math.ceil(this.totalRows / this.pagination.rowsPerPage);
      if (this.pagination.page > pages) this.pagination.page = 1;
      return pages;
    },
    visibleColumns() {
      let columns = this.columns;
      if (this.showNumber) {
        columns = [];
        this.columns.forEach((item, index) => {
          if (index > 0) columns.push(item);
        });
      }
      return columns;
    }
  }
};
</script>

<style lang="css">
</style>



