import Vue from "vue";
import { Bus as Vuedals } from "vuedals";

import { post } from "@/utils/proxy";
import * as types from "./mutation-types";

export const userInfo = async ({ commit }) => {
  const result = await post("app/getUserInfo");
  commit(types.USERINFO, result);
};

export const check = ({ commit }) => {
  commit(types.CHECK);
  userInfo({ commit });
};

export const login = async ({ commit }, user) => {
  const result = await post("login", user);
  if (result.success_message) {
    commit(types.LOGIN, result.jwt);
    userInfo({ commit });
    Vuedals.$emit("close");
    Vue.router.push({
      name: "home.index"
    });
  } else {
    commit(types.LOGIN_ERROR);
  }
};

export const logout = ({ commit }) => {
  commit(types.LOGOUT);
  userInfo({ commit });
  Vue.router.push({
    name: "home.index"
  });
};

export default {
  check,
  login,
  logout
};



