import Vue from "vue";

function submit(requestType, url, data = null) {
  return new Promise((resolve, reject) => {
    Vue.$http[requestType](url, data)
      .then(response => {
        resolve(response.data);
      })
      .catch(({ response }) => {
        if (response) {
          reject(response.data);
        } else {
          reject();
        }
      });
  });
}

function post(url, data = null) {
  return submit("post", url, data);
}

export { submit, post };



