<template>
  <v-app
    id="inspire"
    class="white"
  >
    <v-navigation-drawer
      v-if="authenticated"
      :disable-resize-watcher="true"
      :clipped="$vuetify.breakpoint.lgAndUp"
      v-model="drawer"
      fixed
      app
      :width="280"
    >
      <v-list dense>
        <template v-for="item in menus">
          <template v-if="item.roles.indexOf(parseInt(user.idRole)) != -1">
            <v-layout
              v-if="item.heading"
              :key="item.heading"
              row
              align-center
            >
              <v-flex xs6>
                <v-subheader v-if="item.heading">
                  {{ item.heading }}
                </v-subheader>
              </v-flex>
            </v-layout>
            <v-list-group
              no-action
              v-else-if="item.items"
              v-model="item.active"
              :key="item.title"
              :prepend-icon="item.icon"
              :append-icon="item.model ? 'keyboard_arrow_down' : 'keyboard_arrow_down'"
            >
              <v-list-tile slot="activator">
                <v-list-tile-content>
                  <v-list-tile-title>
                    {{ item.title }}
                  </v-list-tile-title>
                </v-list-tile-content>
              </v-list-tile>
              <v-list-tile
                v-for="(child, i) in item.items"
                :key="i"
                :class="child.active ? 'active': ''"
                :to="'/'+child.path"
                exact
              >
                <v-list-tile-content>
                  <v-list-tile-title>
                    {{ child.title }}
                  </v-list-tile-title>
                </v-list-tile-content>
              </v-list-tile>
            </v-list-group>
            <v-list-tile
              v-else
              :key="item.path"
              :class="item.active ? 'active': ''"
              :to="'/'+item.path"
            >
              <v-list-tile-action>
                <v-icon>{{ item.icon }}</v-icon>
              </v-list-tile-action>
              <v-list-tile-content>
                <v-list-tile-title>
                  {{ item.title }}
                </v-list-tile-title>
              </v-list-tile-content>
            </v-list-tile>
          </template>
        </template>
      </v-list>
    </v-navigation-drawer>
    <v-toolbar
      :clipped-left="$vuetify.breakpoint.lgAndUp"
      dark
      app
      fixed
      height="50"
    >
      <v-toolbar-side-icon
        v-if="authenticated"
        dark
        @click.stop="drawer = !drawer"
      ></v-toolbar-side-icon>
      <v-toolbar-title>IT Inventory</v-toolbar-title>
      <v-spacer></v-spacer>
      <span v-if="authenticated">{{user.username}}</span>
      <v-menu
        offset-x
        v-if="authenticated"
      >
        <v-btn
          icon
          dark
          slot="activator"
          class="grey"
        >
          <v-icon>person</v-icon>
        </v-btn>
        <v-card>
          <v-list>
            <v-list-tile to="/profile">
              <v-list-tile-content>
                <v-list-tile-title>My Profile</v-list-tile-title>
              </v-list-tile-content>
            </v-list-tile>
            <v-list-tile @click="logout()">
              <v-list-tile-content>
                <v-list-tile-title>Logout</v-list-tile-title>
              </v-list-tile-content>
            </v-list-tile>
          </v-list>
        </v-card>
      </v-menu>
    </v-toolbar>
    <v-content>
      <slot></slot>
    </v-content>
    <vuedal></vuedal>
  </v-app>
</template>

<script>
import _ from "lodash";
import Histats from "@/components/Histats";

import { API_LOCATION } from "@/constants";

export default {
  name: "default-layout",
  components: { Histats },
  data() {
    return {
      menuCollapsed: false,
      dialog: false,
      drawer: false,
      drawerHeaderLink: false,
      logoSrc: `${API_LOCATION}image/get/logo?h=40`
    };
  },
  created() {
    this.getActiveLink(this.menus);
  },
  methods: {
    goTo(path) {
      this.$router.push(path);
    },
    getActiveLink(menus) {
      menus.forEach(item => {
        if (item.items) {
          this.getActiveLink(item.items);
          const activeFilter = _.filter(item.items, o => {
            const active = o.active;
            return active;
          });
          if (activeFilter.length > 0) {
            item.active = true;
          } else {
            item.active = false;
          }
        } else if (`/${item.path}` === this.$route.path) {
          item.active = true;
        } else {
          item.active = false;
        }
      });
    },
    logout() {
      this.$store.dispatch("auth/logout");
      this.$router.push("/login");
    }
  },
  computed: {
    authenticated() {
      return this.$store.state.auth.authenticated;
    },
    user() {
      return this.$store.state.auth.user;
    },
    windowSize() {
      return this.$store.state.app.windowSize;
    },
    menus() {
      const menus = [
        {
          icon: "fa-users",
          title: "Data Pengguna",
          path: "pengguna",
          roles: [1]
        },
        {
          icon: "fa-gear",
          title: "Pengaturan Kolom",
          items: [
            {
              icon: "view_module",
              title: "Dokumen Pabean",
              path: "pengaturan-kolom-pabean"
            },
            {
              icon: "view_module",
              title: "Mutasi Bulanan",
              path: "pengaturan-kolom-mutasi"
            },
            {
              icon: "view_module",
              title: "WIP",
              path: "pengaturan-kolom-wip"
            }
          ],
          roles: [1]
        },
        {
          icon: "fa-print",
          title: "Pengaturan Print",
          items: [
            {
              icon: "view_module",
              title: "Dokumen Pabean",
              path: "pengaturan-print-pabean"
            },
            {
              icon: "view_module",
              title: "Mutasi Bulanan",
              path: "pengaturan-print-mutasi"
            },
            {
              icon: "view_module",
              title: "WIP",
              path: "pengaturan-print-wip"
            }
          ],
          roles: [1]
        },
        {
          icon: "fa-folder",
          title: "Data Dokumen Pabean",
          path: "dokumen-pabean",
          roles: [1, 3]
        },
        {
          icon: "fa-calendar",
          title: "Data Mutasi Bulanan",
          path: "mutasi-bulanan",
          roles: [1, 3]
        },
        {
          icon: "fa-calendar-minus-o",
          title: "Data WIP",
          path: "wip",
          roles: [1, 3]
        }
      ];

      return menus;
    }
  },
  watch: {
    $route() {
      this.drawer = false;
      this.getActiveLink(this.menus);
    }
  }
};
</script>
<style scoped>
.toolbar {
  background: #3f51b5 !important;
}

.toolbar-icon {
  background-color: #ffffff;
}

.navigation-drawer > .list .list__tile--active .list__tile__title {
  color: black !important;
  font-weight: bold;
}

.navigation-drawer > .list .active {
  border-right: 3px solid #1976d2;
  background-color: #e0e0e0;
}
.list__tile:after {
  height: 0px !important;
}

.header-left-toolbar {
  width: 280px;
  background-color: #ffffff;
  padding: 0 20px !important;
  margin-left: 0 !important;
  align-items: center;
}

.header-img {
  height: 40px;
}

.header-link {
  margin-left: 20px;
}

.header-link > .btn {
  font-weight: 300 !important;
  border-radius: 0px !important;
}

.footer {
  background-color: transparent !important;
}
.footer-right {
  text-align: right !important;
}

#styled-input {
  height: 40px;
  font-size: 20pt;
}
.styled-input label[for] {
  height: 40px;
  font-size: 20pt;
}
</style>



