/* ============
 * Main File
 * ============
 *
 * Will initialize the application.
 */

import Vue from "vue";

/* ============
 * Plugins
 * ============
 *
 * Import and bootstrap the plugins.
 */

import "./plugins/vuex";
import "./plugins/axios";
import { i18n } from "./plugins/vue-i18n";
import { router } from "./plugins/vue-router";
import "./plugins/vuex-router-sync";
// import './plugins/font-awesome';
import "./plugins/vuetify";
import "./plugins/vue-multiselect";
import "./plugins/vee-validate";
import "./plugins/vuedals";
import "./plugins/v-hotkey";
import "./plugins/vue-datepicker";
import "./plugins/vuedraggable";

/* ============
 * Styling
 * ============
 *
 * Import the application styling.
 * Stylus is used for this boilerplate.
 *
 * If you don't want to use Stylus, that's fine!
 * Replace the stylus directory with the CSS preprocessor you want.
 * Import the entry point here & install the webpack loader.
 *
 * It's that easy...
 *
 * http://stylus-lang.com/
 */

import "./assets/stylus/app.styl";
import "./assets/stylus/grid.styl";
/* ============
 * Main App
 * ============
 *
 * Last but not least, we import the main application.
 */

import BaseLayout from "./layouts/Default";
import MinimalLayout from "./layouts/Minimal";
import App from "./App";
import store from "./store";

import VQueryService from "./components/QueryService";
import VTreeView from "./components/TreeView";
import VSelectView from "./components/SelectView";
import VTableView from "./components/TableView";
import VDateRangePicker from "./components/DateRangePicker";
import VDatepicker from "./components/VDatePicker";

Vue.config.productionTip = false;

Vue.component("base-layout", BaseLayout);
Vue.component("minimal-layout", MinimalLayout);

Vue.component("vdatepicker", VDatepicker);
Vue.component("query-service", VQueryService);
Vue.component("tree-view", VTreeView);
Vue.component("select-view", VSelectView);
Vue.component("table-view", VTableView);
Vue.component("daterangepicker", VDateRangePicker);

store.dispatch("auth/check");

window.eventBus = new Vue({});
/* eslint-disable no-new */
new Vue({
  /**
   * Bind the Vue instance to the HTML.
   */
  el: "#app",

  /**
   * The localization plugin.
   */
  i18n,

  /**
   * The router.
   */
  router,

  /**
   * The Vuex store.
   */
  store,

  /**
   * Will render the application.
   *
   * @param {Function} h Will create an element.
   */
  render: h => h(App)
});



